def max_depth(tree):
    if not tree: return 0
    def depth(i):
        if i >= len(tree) or tree[i] is None: return 0
        return 1 + max(depth(2*i+1), depth(2*i+2))
    return depth(0)

def is_subtree(root, sub):
    if not sub: return True
    if not root: return False
    def same(a, b):
        if a >= len(root) and b >= len(sub): return True
        if a >= len(root) or b >= len(sub): return False
        if root[a] is None and sub[b] is None: return True
        if root[a] is None or sub[b] is None: return False
        if root[a] != sub[b]: return False
        return same(2*a+1, 2*b+1) and same(2*a+2, 2*b+2)
    def search(i):
        if i >= len(root): return False
        if root[i] is not None and root[i] == sub[0] and same(i, 0):
            return True
        return search(2*i+1) or search(2*i+2)
    return search(0)
